#!/usr/bin/env Rscript
args<-grep('^--file=',commandArgs(FALSE),value=TRUE)[1];here<-dirname(normalizePath(sub('^--file=','',args)))
suppressPackageStartupMessages({library(ggplot2);library(cowplot);library(svglite)})
cowplot::set_null_device('agg');navy<-'#315778';gold<-'#93640B';ink<-'#202B37'
e<-subset(read.csv(file.path(here,'exact_curves.csv')),rho==.2);p<-subset(read.csv(file.path(here,'pause_exact_curves.csv')),rho==.2);f<-subset(read.csv(file.path(here,'finite_summary.csv')),rho==.2)
th<-function()theme_classic(base_size=10,base_family='Arial')+theme(text=element_text(colour=ink),axis.text=element_text(size=9,colour=ink),axis.line=element_line(linewidth=.28),axis.ticks=element_line(linewidth=.28),legend.title=element_blank(),legend.position='bottom',legend.text=element_text(size=8),legend.key.width=grid::unit(7,'mm'),plot.margin=margin(17,8,8,17))
xs<-scale_x_continuous(breaks=c(-.16,-.08,0,.08,.16));xl<-expression('Error asymmetry, '*delta)
ctrl<-subset(e,model=='control');alt<-subset(e,model=='directed')
a<-ggplot(ctrl,aes(delta))+geom_hline(yintercept=0,colour=ink,linewidth=.25)+geom_line(aes(y=q1,colour='q1',linetype='q1'),linewidth=.8)+geom_line(aes(y=q2,colour='q2',linetype='q2'),linewidth=.8)+scale_colour_manual(values=c(q1=navy,q2=gold),labels=c(expression(q[1]),expression(q[2])))+scale_linetype_manual(values=c(q1='solid',q2='dashed'),labels=c(expression(q[1]),expression(q[2])))+guides(linetype='none',colour=guide_legend(override.aes=list(linetype=c('solid','dashed'))))+xs+labs(x=xl,y='Adjacent-pair contrast')+th()
b<-ggplot()+geom_hline(yintercept=0,colour=ink,linewidth=.25)+geom_line(data=ctrl,aes(delta,triple,colour='E / R swaps',linetype='E / R swaps'),linewidth=.8)+geom_line(data=p,aes(delta,triple,colour='Errors to P',linetype='Errors to P'),linewidth=.8)+scale_colour_manual(values=c('E / R swaps'=navy,'Errors to P'=gold))+scale_linetype_manual(values=c('E / R swaps'='solid','Errors to P'='dashed'))+guides(linetype='none',colour=guide_legend(override.aes=list(linetype=c('solid','dashed'))))+xs+labs(x=xl,y='Control triple contrast')+th()
c<-ggplot()+geom_hline(yintercept=0,colour=ink,linewidth=.25)+geom_line(data=ctrl,aes(delta,lag2,colour='Reversible',linetype='Reversible'),linewidth=.8)+geom_line(data=alt,aes(delta,lag2,colour='Asymmetric',linetype='Asymmetric'),linewidth=.8)+scale_colour_manual(values=c('Reversible'=navy,'Asymmetric'=gold))+scale_linetype_manual(values=c('Reversible'='solid','Asymmetric'='dashed'))+guides(linetype='none',colour=guide_legend(override.aes=list(linetype=c('dashed','solid'))))+xs+labs(x=xl,y='Lag-two contrast')+th()
f$contrast<-factor(f$contrast,levels=c('triple','lag2'),labels=c('Triple','Lag 2'));f$n<-factor(f$n)
d<-ggplot(f,aes(delta,rate,colour=contrast,linetype=n,shape=n,group=interaction(contrast,n)))+geom_hline(yintercept=.05,colour=ink,linetype='dotted',linewidth=.3)+geom_line(linewidth=.65)+geom_errorbar(aes(ymin=lo,ymax=hi),width=.004,linewidth=.35)+geom_point(size=1.4)+scale_colour_manual(values=c('Triple'=navy,'Lag 2'=gold))+scale_linetype_manual(values=c('300'='solid','3000'='dashed'))+scale_shape_manual(values=c(16,1))+xs+scale_y_continuous(limits=c(0,1.04),breaks=c(0,.25,.5,.75,1))+labs(x=xl,y='Control fraction above threshold')+th()+theme(legend.position='none')+annotate('text',x=-.14,y=.94,label='Triple',hjust=0,colour=navy,family='Arial',size=2.7)+annotate('text',x=-.14,y=.84,label='Lag 2',hjust=0,colour=gold,family='Arial',size=2.7)
g<-ggdraw(plot_grid(a,b,c,d,ncol=2));for(k in 1:4)g<-g+draw_label(c('a','b','c','d')[k],x=c(.008,.508,.008,.508)[k],y=c(.992,.992,.492,.492)[k],hjust=0,vjust=1,fontfamily='Arial',fontface='bold',size=12)
for(ext in c('pdf','svg','eps','png')){f<-file.path(here,paste0('Figure_asymmetric_error.',ext));if(ext=='pdf')ggsave(f,g,width=7.1,height=6.4,device=cairo_pdf,bg='white')else if(ext=='svg')ggsave(f,g,width=7.1,height=6.4,device=svglite,bg='white')else if(ext=='eps')ggsave(f,g,width=7.1,height=6.4,device=cairo_ps,onefile=FALSE,bg='white')else ggsave(f,g,width=7.1,height=6.4,dpi=300,bg='white')}
